import React, { useState } from 'react';
import { Button, CircularProgress, Typography, Box, Alert } from '@mui/material';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import { uploadAttachment } from '../../services/attachmentService';

interface AttachmentUploadProps {
  association: { project_id?: number; task_id?: number; subtask_id?: number };
  onUploadSuccess: () => void;
}

const AttachmentUpload: React.FC<AttachmentUploadProps> = ({ association, onUploadSuccess }) => {
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      const file = event.target.files[0];
      setUploading(true);
      setError(null);

      try {
        await uploadAttachment(file, association);
        onUploadSuccess();
      } catch (err) {
        console.error("Upload failed", err);
        setError("Failed to upload file. Please try again.");
      } finally {
        setUploading(false);
        // Reset the input value so the same file can be selected again if needed
        event.target.value = '';
      }
    }
  };

  return (
    <Box>
      <input
        accept="*/*"
        style={{ display: 'none' }}
        id="raised-button-file"
        multiple={false}
        type="file"
        onChange={handleFileChange}
      />
      <label htmlFor="raised-button-file">
        <Button
          variant="outlined"
          component="span"
          startIcon={uploading ? <CircularProgress size={20} /> : <CloudUploadIcon />}
          disabled={uploading}
        >
          {uploading ? 'Uploading...' : 'Upload File'}
        </Button>
      </label>
      {error && (
        <Alert severity="error" sx={{ mt: 1 }}>
          {error}
        </Alert>
      )}
    </Box>
  );
};

export default AttachmentUpload;

import React, { useState, useEffect } from 'react';
import { 
    Dialog, DialogTitle, DialogContent, DialogActions, Button, 
    FormControl, InputLabel, Select, MenuItem, CircularProgress, 
    Typography, Alert, SelectChangeEvent
} from '@mui/material';
import { getTasks } from '../../services/tasks';
import { createDependency } from '../../services/dependencyService';
import { Task } from '../../types/task';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

interface AddDependencyDialogProps {
    open: boolean;
    onClose: () => void;
    projectId: number;
    dependentTaskId: number; // The task that depends on something
}

const AddDependencyDialog: React.FC<AddDependencyDialogProps> = ({ open, onClose, projectId, dependentTaskId }) => {
    const [prerequisiteId, setPrerequisiteId] = useState<string>('');
    const [error, setError] = useState<string | null>(null);
    const queryClient = useQueryClient();

    // Fetch potential prerequisites (all tasks in project)
    const { data: tasks, isLoading } = useQuery({
        queryKey: ['projectTasks', projectId],
        queryFn: () => getTasks(projectId),
        enabled: open, // Only fetch when dialog is open
    });

    const createMutation = useMutation({
        mutationFn: createDependency,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['taskDependencies', dependentTaskId] });
            onClose();
        },
        onError: () => {
            setError("Failed to create dependency. Check for circular dependencies.");
        }
    });

    const handleSubmit = () => {
        if (!prerequisiteId) return;
        setError(null);
        createMutation.mutate({
            dependent_id: dependentTaskId,
            prerequisite_id: Number(prerequisiteId)
        });
    };

    const handleChange = (event: SelectChangeEvent) => {
        setPrerequisiteId(event.target.value as string);
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle>Add Dependency</DialogTitle>
            <DialogContent>
                <Typography variant="body2" sx={{ mb: 2 }}>
                    Select a task that must be completed <b>before</b> the current task can start.
                </Typography>

                {isLoading ? (
                    <CircularProgress />
                ) : (
                    <FormControl fullWidth>
                        <InputLabel id="prerequisite-select-label">Prerequisite Task</InputLabel>
                        <Select
                            labelId="prerequisite-select-label"
                            value={prerequisiteId}
                            label="Prerequisite Task"
                            onChange={handleChange}
                        >
                            {tasks?.filter(t => t.id !== dependentTaskId).map((task) => (
                                <MenuItem key={task.id} value={task.id}>
                                    {task.name} (ID: {task.id})
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                )}

                {error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose}>Cancel</Button>
                <Button onClick={handleSubmit} variant="contained" disabled={!prerequisiteId || createMutation.isPending}>
                    {createMutation.isPending ? 'Adding...' : 'Add Dependency'}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default AddDependencyDialog;

import React from 'react';
import { Box, Grid, Typography, Paper, Tooltip } from '@mui/material';
import { ContributionData } from '../../types/user';
import { useQuery } from '@tanstack/react-query';
import { getMyContributions } from '../../services/users';
import { format, addDays, startOfWeek, isSameDay } from 'date-fns';

const DAYS_IN_GRAPH = 365; // ~1 year

// Helper to get all dates for the graph
const getDatesForGraph = (days: number): Date[] => {
  const dates: Date[] = [];
  let currentDate = addDays(new Date(), -days + 1); // Start date to show N days
  while (dates.length < days) {
    dates.push(currentDate);
    currentDate = addDays(currentDate, 1);
  }
  return dates;
};

const ContributionGraph: React.FC = () => {
  const { data: contributions = [], isLoading, error } = useQuery<ContributionData[]>({
    queryKey: ['myContributions', DAYS_IN_GRAPH],
    queryFn: () => getMyContributions(DAYS_IN_GRAPH),
  });

  const allDates = getDatesForGraph(DAYS_IN_GRAPH);

  // Map contributions for easy lookup
  const contributionMap = new Map<string, number>();
  contributions.forEach(c => {
    contributionMap.set(format(new Date(c.date), 'yyyy-MM-dd'), c.count);
  });

  if (isLoading) {
    return <Typography>Loading contributions...</Typography>;
  }

  if (error) {
    return <Alert severity="error">Failed to load contributions: {error.message}</Alert>;
  }

  // Determine the color scale based on contribution count
  const getColor = (count: number) => {
    if (count === 0) return '#ebedf0'; // Lightest gray
    if (count < 5) return '#9be9a8';
    if (count < 10) return '#40c463';
    if (count < 15) return '#30a14e';
    return '#216e39'; // Darkest green
  };

  // Group dates by week for rendering (GitHub style)
  const weeks: Date[][] = [];
  let currentWeek: Date[] = [];
  allDates.forEach((date, index) => {
    // Start a new week if it's Sunday (0) or the first day
    if (isSameDay(startOfWeek(date, { weekStartsOn: 0 }), date) || index === 0) {
      if (currentWeek.length > 0) {
        weeks.push(currentWeek);
      }
      currentWeek = [];
    }
    currentWeek.push(date);
  });
  if (currentWeek.length > 0) {
    weeks.push(currentWeek);
  }


  return (
    <Box sx={{ p: 2, border: '1px solid #e0e0e0', borderRadius: '8px', overflowX: 'auto', mt: 4 }}>
      <Typography variant="h6" gutterBottom>Your Task Contributions (Last Year)</Typography>
      <Box sx={{ display: 'flex', flexDirection: 'row', gap: '2px' }}>
        {weeks.map((week, weekIndex) => (
          <Box key={weekIndex} sx={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
            {week.map((date) => {
              const dateString = format(date, 'yyyy-MM-dd');
              const count = contributionMap.get(dateString) || 0;
              return (
                <Tooltip key={dateString} title={`${count} contributions on ${format(date, 'MMM d, yyyy')}`}>
                  <Box
                    sx={{
                      width: 12,
                      height: 12,
                      bgcolor: getColor(count),
                      borderRadius: '2px',
                      cursor: 'pointer',
                    }}
                  />
                </Tooltip>
              );
            })}
          </Box>
        ))}
      </Box>
    </Box>
  );
};

export default ContributionGraph;

import React, { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Box, Typography, Paper, Tooltip, Zoom } from '@mui/material';
import { addDays, format, differenceInDays, min, max, isValid, parseISO } from 'date-fns';
import { getSummaryGanttData } from '../../services/projects'; // Assuming this service call exists
import { Project } from '../../types/project'; // Import Project type
import { Task } from '../../types/task'; // Import Task type

interface GanttItem {
    id: string | number;
    name: string;
    start: Date;
    end: Date;
    status: string;
    type: 'Project' | 'Task' | 'Subtask';
    color: string;
    parentName?: string; // For tasks/subtasks, to show their parent project/task
}

const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
        case 'completed': return '#4caf50';
        case 'in progress': return '#2196f3';
        case 'review': return '#ff9800';
        case 'on hold': return '#d32f2f'; // Red for on hold
        default: return '#9e9e9e';
    }
};

const safeDate = (d: string | undefined, fallback: Date): Date => {
    if (!d) return fallback;
    const parsed = parseISO(d);
    return isValid(parsed) ? parsed : fallback;
};

const DashboardGantt: React.FC = () => {
    const { data: projects, isLoading, error } = useQuery<Project[]>({
        queryKey: ['summaryGanttData'],
        queryFn: getSummaryGanttData, // Fetch aggregated data
    });

    const { processedItems, minDate, totalDays } = useMemo(() => {
        if (!projects || projects.length === 0) return { processedItems: [], minDate: new Date(), totalDays: 0 };

        const items: GanttItem[] = [];
        const itemDates: Date[] = [];

        projects.forEach(p => {
            const projectStart = safeDate(p.start_date, new Date());
            const projectEnd = safeDate(p.end_date, addDays(projectStart, 7)); // Default to 7 days if no end
            itemDates.push(projectStart, projectEnd);
            items.push({ 
                id: `proj-${p.id}`, 
                name: p.name, 
                start: projectStart, 
                end: projectEnd, 
                status: p.status, 
                type: 'Project',
                color: getStatusColor(p.status)
            });

            p.tasks?.forEach((t: Task & { project_name?: string }) => { // Task can also have project_name from backend
                const taskStart = safeDate(t.start_date, projectStart);
                const taskEnd = safeDate(t.end_date, addDays(taskStart, 3));
                itemDates.push(taskStart, taskEnd);
                items.push({ 
                    id: `task-${t.id}`, 
                    name: t.name, 
                    start: taskStart, 
                    end: taskEnd, 
                    status: t.status, 
                    type: 'Task',
                    color: getStatusColor(t.status),
                    parentName: p.name
                });

                t.subtasks?.forEach((s: any) => { // Subtask doesn't have a direct type here
                    const subtaskStart = safeDate(s.start_date, taskStart);
                    const subtaskEnd = safeDate(s.end_date, addDays(subtaskStart, 1));
                    itemDates.push(subtaskStart, subtaskEnd);
                    items.push({ 
                        id: `sub-${s.id}`, 
                        name: s.name, 
                        start: subtaskStart, 
                        end: subtaskEnd, 
                        status: s.status, 
                        type: 'Subtask',
                        color: getStatusColor(s.status),
                        parentName: t.name
                    });
                });
            });
        });

        if (itemDates.length === 0) return { processedItems: [], minDate: new Date(), totalDays: 0 };

        const minD = min(itemDates);
        const maxD = addDays(max(itemDates), 2); // Buffer
        const days = differenceInDays(maxD, minD) || 1;

        return { processedItems: items.sort((a,b) => a.start.getTime() - b.start.getTime()), minDate: minD, totalDays: days };
    }, [projects]);

    if (isLoading) {
        return <Typography>Loading summary Gantt...</Typography>;
    }

    if (error) {
        return <Alert severity="error">Error loading summary Gantt: {error.message}</Alert>;
    }

    if (!projects || projects.length === 0 || processedItems.length === 0) {
        return (
            <Paper sx={{ p: 4, textAlign: 'center', borderRadius: 2, bgcolor: 'background.default', mt: 4 }}>
                <Typography color="text.secondary">No projects or tasks with dates to display in Gantt chart.</Typography>
            </Paper>
        );
    }

    return (
        <Paper sx={{ p: 3, mb: 4, overflow: 'hidden', borderRadius: 3, boxShadow: 3 }}>
            <Typography variant="h6" gutterBottom fontWeight="bold" sx={{ mb: 3 }}>
                All Project Timeline Summary
            </Typography>

            <Box sx={{ overflowX: 'auto', pb: 2 }}>
                <Box sx={{ minWidth: 800, position: 'relative' }}>

                    {/* Header: Month/Day Ticks */}
                    <Box sx={{ display: 'flex', borderBottom: '1px solid #eee', mb: 2, pb: 1 }}>
                        <Box sx={{ width: 200, flexShrink: 0, fontWeight: 'bold', color: 'text.secondary' }}>Item</Box>
                        <Box sx={{ flexGrow: 1, position: 'relative', height: 24 }}>
                            {Array.from({ length: totalDays > 30 ? Math.ceil(totalDays / 30) + 1 : totalDays }).map((_, i) => {
                                const tickDate = addDays(minDate, i * (totalDays > 30 ? 30 : 1)); // Show monthly or daily ticks
                                const left = (differenceInDays(tickDate, minDate) / totalDays) * 100;
                                if (left > 100) return null;
                                return (
                                    <Typography key={i} variant="caption" sx={{ position: 'absolute', left: `${left}%`, transform: 'translateX(-50%)', color: 'text.disabled' }}>
                                        {isValid(tickDate) ? format(tickDate, totalDays > 30 ? 'MMM yy' : 'MMM d') : ''}
                                    </Typography>
                                );
                            })}
                        </Box>
                    </Box>

                    {/* Rows */}
                    {processedItems.map((item) => {
                        const startOffset = differenceInDays(item.start, minDate);
                        const duration = differenceInDays(item.end, item.start) || 1;
                        const leftPercent = Math.max(0, (startOffset / totalDays) * 100);
                        const widthPercent = Math.min(100 - leftPercent, (duration / totalDays) * 100);

                        return (
                            <Box key={item.id} sx={{ display: 'flex', alignItems: 'center', mb: 1.5, height: 32, '&:hover': { bgcolor: 'action.hover', borderRadius: 1 } }}>
                                {/* Label */}
                                <Box sx={{ width: 200, flexShrink: 0, pr: 2, display: 'flex', alignItems: 'center' }}>
                                    <Typography variant="body2" noWrap sx={{
                                        fontWeight: item.type === 'Project' ? 600 : (item.type === 'Task' ? 500 : 400),
                                        pl: item.type === 'Subtask' ? 4 : (item.type === 'Task' ? 2 : 0),
                                        color: item.type === 'Subtask' ? 'text.secondary' : 'text.primary'
                                    }}>
                                        {item.type === 'Subtask' && '↳ '} {item.name}
                                        {item.parentName && item.type !== 'Project' && (
                                            <Typography variant="caption" color="text.disabled" sx={{ ml: 0.5 }}>
                                                ({item.parentName})
                                            </Typography>
                                        )}
                                    </Typography>
                                </Box>

                                {/* Bar */}
                                <Box sx={{ flexGrow: 1, position: 'relative', height: '100%' }}>
                                    <Tooltip
                                        title={
                                            <Box sx={{ p: 0.5 }}>
                                                <Typography variant="subtitle2">{item.name}</Typography>
                                                <Typography variant="caption" display="block">
                                                    {item.type} • {isValid(item.start) ? format(item.start, 'MMM d') : '?'} - {isValid(item.end) ? format(item.end, 'MMM d') : '?'}
                                                </Typography>
                                                <Typography variant="caption">{item.status}</Typography>
                                            </Box>
                                        }
                                        TransitionComponent={Zoom}
                                        arrow
                                    >
                                        <Box sx={{
                                            position: 'absolute',
                                            left: `${leftPercent}%`,
                                            width: `${Math.max(widthPercent, 0.5)}%`,
                                            height: item.type === 'Project' ? 24 : 20,
                                            top: item.type === 'Project' ? 4 : 6,
                                            bgcolor: item.color,
                                            borderRadius: 4,
                                            cursor: 'pointer',
                                            transition: 'width 0.3s, left 0.3s',
                                            boxShadow: 1,
                                            '&:hover': { filter: 'brightness(1.1)', transform: 'scaleY(1.1)' }
                                        }} />
                                    </Tooltip>
                                </Box>
                            </Box>
                        );
                    })}
                </Box>
            </Box>
        </Paper>
    );
};

