import React from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Card, CardContent, Typography, Box, Avatar, Chip, useTheme, alpha } from '@mui/material';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import { Task } from '../../types/task';

interface TaskCardProps {
    task: Task;
    onClick?: (task: Task) => void;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, onClick }) => {
    const theme = useTheme();
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: task.id });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
    };

    const getPriorityColor = (priority?: string) => {
        switch (priority) {
            case 'high': return theme.palette.error.main;
            case 'medium': return theme.palette.warning.main;
            case 'low': return theme.palette.success.main;
            default: return theme.palette.text.secondary;
        }
    };

    return (
        <Card
            ref={setNodeRef}
            style={style}
            {...attributes}
            {...listeners}
            onClick={() => onClick && onClick(task)}
            sx={{
                mb: 2,
                cursor: 'grab',
                border: '1px solid',
                borderColor: 'divider',
                '&:hover': {
                    borderColor: 'primary.main',
                    boxShadow: `0 4px 12px ${alpha(theme.palette.primary.main, 0.1)} `
                }
            }}
        >
            <CardContent sx={{ p: 2, '&:last-child': { pb: 2 } }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                    {task.priority && (
                        <Chip
                            label={task.priority}
                            size="small"
                            sx={{
                                height: 20,
                                fontSize: '0.7rem',
                                bgcolor: alpha(getPriorityColor(task.priority), 0.1),
                                color: getPriorityColor(task.priority),
                                textTransform: 'capitalize'
                            }}
                        />
                    )}
                </Box>
                <Typography variant="subtitle2" fontWeight="600" sx={{ mb: 2 }}>
                    {task.name}
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, color: 'text.secondary' }}>
                        <AccessTimeIcon sx={{ fontSize: 16 }} />
                        <Typography variant="caption">{task.due_date ? new Date(task.due_date).toLocaleDateString() : 'No date'}</Typography>
                    </Box>
                    <Avatar sx={{ width: 24, height: 24, fontSize: '0.75rem' }}>
                        {task.assignee ? task.assignee.charAt(0) : 'U'}
                    </Avatar>
                </Box>
            </CardContent>
        </Card>
    );
};

